"use client";

import { useState } from "react";

export default function Hero() {
  const [videoLoaded, setVideoLoaded] = useState(false);

  return (
    <section className="relative flex h-[75vh] items-center justify-center overflow-hidden text-center text-white md:h-[90vh]">
      <div className="absolute inset-0 z-[1] bg-transparent">
        <video
          className={`h-full w-full object-cover object-center transition-opacity duration-300 ease-out xl:object-[50%_20%] ${
            videoLoaded ? "opacity-100" : "opacity-100"
          }`}
          autoPlay
          loop
          muted
          playsInline
          preload="auto"
          onCanPlay={() => setVideoLoaded(true)}
        >
          <source
            src="https://res.cloudinary.com/dtiaycw2o/video/upload/v1756199958/servicevideo_tmmdcb.webm"
            type="video/webm"
          />
          Your browser does not support the video tag.
        </video>
      </div>

      <div className="relative z-[2] mx-auto max-w-[800px] px-4 py-5">
        <h1 className="mb-5 text-[2rem] font-bold drop-shadow-[2px_1px_5px_white] md:text-[3rem]">
          Welcome to Our Services
        </h1>
        <p className="mb-8 text-base font-normal md:text-[1.3rem]">
          Discover our wide range of services tailored for you.
        </p>
        <button className="rounded-md border-none bg-purple-700 px-6 py-3 text-base font-medium text-white transition-colors duration-300 hover:bg-[#5f12ed]">
          Variety of Makeup
        </button>
      </div>
    </section>
  );
}